__device__ __forceinline__ uint64_t tcgen05_smem_descriptor(
    const float* pointer
) {
    const uint64_t address = static_cast<uint64_t>(
        __cvta_generic_to_shared(pointer)
    );
    return ((address >> 4) & 0x3fffull)
        | (128ull << 16)
        | (8ull << 32)
        | (1ull << 46);
}

__device__ __forceinline__ void compensated_rankk_16_tcgen05(
    float* tile,
    float* packed_buffer,
    uint32_t tmem_base,
    uint64_t* mma_barrier,
    int panel
) {
    constexpr int N = 128;
    constexpr float RESIDUAL_SCALE = 32.0f;
    constexpr float INVERSE_RESIDUAL_SCALE = 1.0f / RESIDUAL_SCALE;
    const int tid = threadIdx.x;
    const int warp = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;
    const int stop = panel + 16;
    const int trailing = N - stop;

    for (int logical = tid; logical < trailing * 16;
         logical += blockDim.x) {
        const int row = stop + logical / 16;
        const int k = logical % 16;
        const int physical = (k / 8) * 1024
            + ((k & 7) / 4) * 512 + row * 4 + (k & 3);
        const float original = tile[row * N + panel + k];
        const float high = wmma::__float_to_tf32(original);
        packed_buffer[physical] = high;
    }
    asm volatile("fence.proxy.async.shared::cta;" : : : "memory");
    __syncthreads();

    const uint64_t high_descriptor_0 =
        tcgen05_smem_descriptor(packed_buffer);
    const uint64_t high_descriptor_1 =
        tcgen05_smem_descriptor(packed_buffer + 1024);
    const uint64_t high_b_descriptor_0 =
        tcgen05_smem_descriptor(packed_buffer + stop * 4);
    const uint64_t high_b_descriptor_1 =
        tcgen05_smem_descriptor(packed_buffer + 1024 + stop * 4);
    const uint32_t instruction_descriptor =
        (1u << 4) | (2u << 7) | (2u << 10)
        | ((trailing / 8) << 17) | (8u << 24);

    if (tid == 0) {
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base, high_descriptor_0, high_b_descriptor_0,
            instruction_descriptor, false
        );
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base, high_descriptor_1, high_b_descriptor_1,
            instruction_descriptor, true
        );
        cuda::ptx::tcgen05_commit(
            cuda::ptx::cta_group_1, mma_barrier
        );
    }
    while (!cuda::ptx::mbarrier_try_wait_parity(mma_barrier, 0)) {}
    cuda::ptx::tcgen05_fence_after_thread_sync();

    for (int logical = tid; logical < trailing * 16;
         logical += blockDim.x) {
        const int row = stop + logical / 16;
        const int k = logical % 16;
        const int physical = (k / 8) * 1024
            + ((k & 7) / 4) * 512 + row * 4 + (k & 3);
        const float original = tile[row * N + panel + k];
        const float high = wmma::__float_to_tf32(original);
        packed_buffer[physical] = wmma::__float_to_tf32(
            fmaf(RESIDUAL_SCALE, original - high, high)
        );
    }
    asm volatile("fence.proxy.async.shared::cta;" : : : "memory");
    __syncthreads();

    if (tid == 0) {
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base + 128, high_descriptor_0,
            high_b_descriptor_0, instruction_descriptor, false
        );
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base + 128, high_descriptor_1,
            high_b_descriptor_1, instruction_descriptor, true
        );
        cuda::ptx::tcgen05_commit(
            cuda::ptx::cta_group_1, mma_barrier
        );
    }
    while (!cuda::ptx::mbarrier_try_wait_parity(mma_barrier, 1)) {}
    cuda::ptx::tcgen05_fence_after_thread_sync();

    const int row_group = warp & 3;
    const int column_group = warp / 4;
    const int row = row_group * 32 + lane;
    #pragma unroll
    for (int half = 0; half < 2; ++half) {
        const int first_column = column_group * 16 + half * 64;
        if (first_column < trailing) {
            const uint32_t address = tmem_base
                + ((row_group * 32) << 16) + first_column;
            uint32_t high_product[16];
            uint32_t scaled_product[16];
            cuda::ptx::tcgen05_ld_32x32b(high_product, address);
            cuda::ptx::tcgen05_ld_32x32b(
                scaled_product, address + 128
            );
            cuda::ptx::tcgen05_wait_ld();
            #pragma unroll
            for (int element = 0; element < 16; ++element) {
                const int column = stop + first_column + element;
                if (row >= column) {
                    const float high =
                        __uint_as_float(high_product[element]);
                    const float scaled =
                        __uint_as_float(scaled_product[element]);
                    const float correction =
                        (scaled - high) * INVERSE_RESIDUAL_SCALE;
                    tile[row * N + column] -= high + correction;
                }
            }
            if (first_column == 0 && warp == stop / 32) {
                factor_panel_16_warp(tile, stop, stop & 31);
            }
        }
    }
    __syncthreads();
}

__global__ void blocked_wmma16_cholesky_128(
    const float* __restrict__ input,
    float* __restrict__ output
) {
    constexpr int N = 128;
    extern __shared__ float tile[];
    float* packed_buffer = tile + N * N;
    uint64_t* mma_barrier = reinterpret_cast<uint64_t*>(
        packed_buffer + N * 16
    );
    uint32_t* tmem_slot = reinterpret_cast<uint32_t*>(mma_barrier + 1);
    const int tid = threadIdx.x;
    const long long base = static_cast<long long>(blockIdx.x) * N * N;
    const float* src = input + base;
    float* dst = output + base;
    for (int vector = tid; vector < N * N / 4;
         vector += blockDim.x) {
        const int row = vector / (N / 4);
        const int col = vector % (N / 4) * 4;
        float4 values = reinterpret_cast<const float4*>(src)[vector];
        if (row < col + 3) values.w = 0.0f;
        if (row < col + 2) values.z = 0.0f;
        if (row < col + 1) values.y = 0.0f;
        if (row < col) values.x = 0.0f;
        reinterpret_cast<float4*>(tile)[vector] = values;
    }
    __syncthreads();

    if (tid < 32) {
        cuda::ptx::tcgen05_alloc(
            cuda::ptx::cta_group_1, tmem_slot, 256
        );
    }
    if (tid == 0) {
        cuda::ptx::mbarrier_init(mma_barrier, 1);
    }
    __syncthreads();
    const uint32_t tmem_base = *tmem_slot;

    factor_panel_16(tile, 0);
    #pragma unroll
    for (int panel = 0; panel + 16 < N; panel += 16) {
        solve_panel_16(tile, panel);
        compensated_rankk_16_tcgen05(
            tile, packed_buffer, tmem_base, mma_barrier, panel
        );
    }

    if (tid < 32) {
        cuda::ptx::tcgen05_relinquish_alloc_permit(
            cuda::ptx::cta_group_1
        );
        cuda::ptx::tcgen05_dealloc(
            cuda::ptx::cta_group_1, tmem_base, 256
        );
    }

    for (int vector = tid; vector < N * N / 4;
         vector += blockDim.x) {
        const int row = vector / (N / 4);
        const int col = vector % (N / 4) * 4;
        float4 values = reinterpret_cast<const float4*>(tile)[vector];
        if (row < col + 3) values.w = 0.0f;
        if (row < col + 2) values.z = 0.0f;
        if (row < col + 1) values.y = 0.0f;
        if (row < col) values.x = 0.0f;
        reinterpret_cast<float4*>(dst)[vector] = values;
    }
}

