  99	{
 100	  uint64_t desc_ = 0;
 101	  // Bitfield implementation avoids the need for shifts in assignment
 102	  struct {
 103	    // start_address, bit [0,14), 4LSB not included
 104	    uint16_t start_address_ : 14, : 2;                     // 14 bits [0,14), 2 bits unused
 105	    // leading dimension byte offset, bit [16,30), 4LSB not included
 106	    uint16_t leading_byte_offset_ : 14, : 2;               // 14 bits [0,14), 2 bits unused
 107	    // stride dimension byte offset, bit [32,46), 4LSB not included
 108	    uint16_t stride_byte_offset_ : 14, version_ : 2;       // 14 bits [0,14), 2 bits [14,16)
 109	    // base_offset, bit [49,52). leading_byte_offset_mode, bit [52,53).
 110	    uint8_t : 1, base_offset_ : 3, lbo_mode_ : 1, : 3;     // 1 bit unused, 3 bits [1,4), 1 bit [4,5), 3 bits unused
 111	    // layout type, bit [61,64), SWIZZLE_NONE matrix descriptor = 0, SWIZZLE_128B matrix descriptor = 2, SWIZZLE_64B descriptor = 4, SWIZZLE_32B descriptor = 6, SWIZZLE_128B_BASE32B = 1, N/A = 3, N/A = 5, N/A = 7
 112	    uint8_t : 5, layout_type_ : 3;                         // 6 bits unused, 3 bits [5,8)
 113	  };
 114	  // Seperate the field, as we may only update one part of desc
 115	  struct {
 116	    uint32_t lo;
 117	    uint32_t hi;
 118	  };
